const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "// El cliente se genera dentro del repo (no en node_modules): con pnpm el\n// enlace `.prisma/client` que espera `@prisma/client` no siempre queda donde\n// lo busca, y `tsx` (ESM puro) falla al importarlo. Generarlo aqui hace que la\n// ruta sea explicita y funcione igual en Next y en los scripts.\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------------------\n// AUTENTICACION (Better Auth)\n//\n// Es lo unico que este proyecto crea en la base. Las tablas de datos de abajo\n// ya existian en coopvalili_db con datos productivos y se describen tal como\n// estan (ver prisma/migrations/*_baseline_datos_motor).\n//\n// Los roles son solo ADMIN y COLABORADOR. La base venia con USER del sistema\n// anterior: la migracion convierte esas filas a COLABORADOR y saca el valor\n// del enum.\n// ---------------------------------------------------------------------------\n\nenum Role {\n  ADMIN\n  COLABORADOR\n}\n\n/// Usuario de la aplicacion. Better Auth es el dueno de esta tabla:\n/// la contrasena vive hasheada en Account, no aqui.\nmodel User {\n  id               String   @id @default(cuid())\n  name             String\n  email            String   @unique\n  emailVerified    Boolean  @default(false)\n  image            String?\n  role             Role     @default(COLABORADOR)\n  active           Boolean  @default(false)\n  /// Segundo factor activo. Solo aplica al login con contrasena: quien entra\n  /// por Microsoft ya paso el MFA de Entra ID.\n  twoFactorEnabled Boolean  @default(false)\n  createdAt        DateTime @default(now()) @db.Timestamptz(6)\n  updatedAt        DateTime @default(now()) @updatedAt @db.Timestamptz(6)\n\n  sessions   Session[]\n  accounts   Account[]\n  twoFactors TwoFactor[]\n\n  @@index([email], map: \"idx_user_email\")\n  @@index([role], map: \"idx_user_role\")\n}\n\n/// Sesion activa. El token es el que viaja en la cookie httpOnly y es lo que\n/// autoriza cada accion en el sistema.\nmodel Session {\n  id        String   @id @default(cuid())\n  token     String   @unique\n  userId    String\n  expiresAt DateTime @db.Timestamptz(6)\n  ipAddress String?\n  userAgent String?\n  createdAt DateTime @default(now()) @db.Timestamptz(6)\n  updatedAt DateTime @default(now()) @updatedAt @db.Timestamptz(6)\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([token], map: \"idx_session_token\")\n  @@index([userId], map: \"idx_session_userid\")\n  @@map(\"session\")\n}\n\n/// Credenciales por proveedor. Para email+password guarda el hash en password.\nmodel Account {\n  id                    String    @id @default(cuid())\n  accountId             String\n  providerId            String\n  /// Identificador del emisor que usa Better Auth 1.7 (ej: local:credential).\n  issuer                String?\n  userId                String\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime? @db.Timestamptz(6)\n  refreshTokenExpiresAt DateTime? @db.Timestamptz(6)\n  scope                 String?\n  password              String?\n  createdAt             DateTime  @default(now()) @db.Timestamptz(6)\n  updatedAt             DateTime  @default(now()) @updatedAt @db.Timestamptz(6)\n  user                  User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([providerId, accountId], map: \"uq_account_provider\")\n  @@index([userId], map: \"idx_account_userid\")\n  @@map(\"account\")\n}\n\n/// Tokens de un solo uso: verificacion de correo y reset de contrasena.\nmodel Verification {\n  id         String   @id @default(cuid())\n  identifier String\n  value      String\n  expiresAt  DateTime @db.Timestamptz(6)\n  createdAt  DateTime @default(now()) @db.Timestamptz(6)\n  updatedAt  DateTime @default(now()) @updatedAt @db.Timestamptz(6)\n\n  @@index([identifier], map: \"idx_verification_identifier\")\n  @@map(\"verification\")\n}\n\n/// El segundo factor de un usuario: el secreto TOTP que comparte con su app de\n/// autenticacion y los codigos de respaldo para cuando pierde el telefono.\n///\n/// `failedVerificationCount` y `lockedUntil` frenan la fuerza bruta contra el\n/// codigo: seis digitos se adivinan rapido si se puede intentar sin limite.\nmodel TwoFactor {\n  id                      String    @id @default(cuid())\n  userId                  String\n  secret                  String\n  backupCodes             String\n  verified                Boolean   @default(false)\n  failedVerificationCount Int       @default(0)\n  lockedUntil             DateTime? @db.Timestamptz(6)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId], map: \"idx_two_factor_userid\")\n  @@map(\"twoFactor\")\n}\n\n/// Contador de peticiones por clave (IP + ruta). Better Auth lo usa para frenar\n/// la fuerza bruta contra el login.\n///\n/// Vive en la base y no en memoria porque con varias instancias cada una\n/// tendria su propio contador, y bastaria repartir los intentos entre ellas\n/// para saltarse el limite.\nmodel RateLimit {\n  id          String @id @default(cuid())\n  key         String @unique\n  count       Int\n  /// Epoch en milisegundos, no DateTime: asi lo escribe Better Auth.\n  lastRequest BigInt\n\n  @@map(\"rateLimit\")\n}\n\n// ---------------------------------------------------------------------------\n// DATOS DEL MOTOR\n//\n// Todo lo de aqui abajo ya existe en la base con datos productivos. Se\n// describe tal cual: no se renombra ninguna tabla ni se cambia la nulabilidad\n// de ninguna columna. Lo unico que este proyecto agrego es\n// valida1_results.gestionado_nota.\n// ---------------------------------------------------------------------------\n\nmodel valida1_results {\n  id              BigInt    @id @default(autoincrement())\n  radicado        String    @unique\n  cedula          String?\n  request_json    Json?\n  response_json   Json?\n  created_at      DateTime  @default(now()) @db.Timestamptz(6)\n  updated_at      DateTime  @default(now()) @db.Timestamptz(6)\n  gestionado_at   DateTime? @db.Timestamptz(6)\n  gestionado_by   String?\n  /// Observacion que deja el negociador al gestionar (opcional).\n  gestionado_nota String?\n\n  /// Override manual del estado. El estado normalmente se DERIVA de los\n  /// payloads del motor; cuando este campo tiene valor, gana sobre las reglas\n  /// derivadas. Se guarda quien y cuando porque el cambio lo hace una persona y\n  /// un estado como `aprobado` implica desembolso: sin traza no hay forma de\n  /// auditar quien lo movio. Ponerlo en NULL devuelve la solicitud al estado\n  /// derivado, sin perder nada.\n  estado_manual    String?\n  estado_manual_at DateTime? @db.Timestamptz(6)\n  estado_manual_by String?\n\n  credito_decisiones    credito_decisiones?\n  document_results      document_results[]\n  documentos            documentos[]\n  identity_validations  identity_validations?\n  motor_data_results    motor_data_results[]\n  motor_process_results motor_process_results?\n  motor_ejecuciones     motor_ejecuciones[]\n\n  @@index([cedula], map: \"idx_valida1_cedula\")\n}\n\n/// Indice de los archivos subidos. El contenido vive en Azure Blob Storage;\n/// aqui solo se guarda el puntero (container + blob_name, al estilo bucket +\n/// key de S3) junto con los metadatos y el estado. La FK a valida1_results\n/// garantiza que no se pueda adjuntar un documento a una solicitud que no\n/// existe.\nmodel documentos {\n  id       BigInt @id @default(autoincrement())\n  radicado String\n  cedula   String\n\n  // Puntero al blob. `container` se guarda explicito para soportar una futura\n  // migracion de contenedor sin perder la referencia de los ya existentes.\n  container String @default(\"documentos\")\n  blob_name String\n\n  // Metadatos del archivo\n  nombre_original String\n  mime_type       String?\n  size_bytes      BigInt?\n  /// SHA-256 del contenido: permite detectar que se subio dos veces el mismo\n  /// archivo.\n  sha256          String? @db.Char(64)\n  /// Version del blob en Azure (cambia con cada sobrescritura).\n  etag            String?\n\n  /// Tipo/carpeta del documento. Texto libre (p. ej. \"Pagare\", \"Cedula\").\n  tipo_documento String @default(\"Documentos generales\")\n\n  /// Estado del documento: pendiente | revision | validado (manuales) y\n  /// pendiente_firma | firmado (los pone el sistema via ZapSign).\n  estado String @default(\"pendiente\")\n\n  // Borrado logico: nunca se borra el blob ni la fila.\n  eliminado  Boolean   @default(false)\n  deleted_at DateTime? @db.Timestamptz(6)\n\n  subido_por String?\n  created_at DateTime @default(now()) @db.Timestamptz(6)\n  updated_at DateTime @default(now()) @updatedAt @db.Timestamptz(6)\n\n  valida1_results   valida1_results     @relation(fields: [radicado], references: [radicado], onUpdate: NoAction, map: \"fk_documentos_valida1\")\n  firma_solicitudes firma_solicitudes[]\n\n  @@unique([container, blob_name], map: \"uq_documentos_blob\")\n  @@index([radicado], map: \"idx_documentos_radicado\")\n  @@index([cedula], map: \"idx_documentos_cedula\")\n  @@index([radicado, estado], map: \"idx_documentos_radicado_estado\")\n}\n\n/// Envios a firma electronica (ZapSign). Un documento puede tener varios\n/// envios (reenvios, intentos fallidos): el vigente es el mas reciente con\n/// status \"pending\". El webhook de ZapSign localiza la fila por\n/// `zapsign_token`.\nmodel firma_solicitudes {\n  id           BigInt @id @default(autoincrement())\n  documento_id BigInt\n  radicado     String\n\n  /// Token del documento en ZapSign. Es la llave que trae el webhook.\n  zapsign_token   String  @unique\n  /// open_id de ZapSign (identificador numerico visible en su panel).\n  zapsign_open_id Int?\n  /// URL de firma del firmante: se le reenvia si no recibio el correo.\n  sign_url        String?\n  /// Token del firmante en ZapSign (distinto del token del documento).\n  signer_token    String?\n\n  // Datos del firmante tal como se enviaron (el firmante puede editarlos en\n  // ZapSign, asi que esto es lo solicitado, no necesariamente lo final).\n  firmante_nombre String\n  firmante_email  String?\n  firmante_phone  String?\n\n  /// Canales por los que ZapSign notifico al firmante.\n  canal_email    Boolean @default(true)\n  canal_whatsapp Boolean @default(false)\n\n  /// Estado del envio: pending | signed | refused | error.\n  status String @default(\"pending\")\n\n  /// etag del blob antes de sobrescribirlo con el PDF firmado: deja rastro de\n  /// que existio una version sin firmar (el contenido en si no se conserva).\n  etag_original String?\n\n  /// Payload crudo del ultimo webhook recibido (auditoria y diagnostico).\n  webhook_json Json?\n\n  enviado_por String?\n  created_at  DateTime  @default(now()) @db.Timestamptz(6)\n  updated_at  DateTime  @updatedAt @db.Timestamptz(6)\n  signed_at   DateTime? @db.Timestamptz(6)\n\n  documento documentos @relation(fields: [documento_id], references: [id], onDelete: Cascade, map: \"fk_firma_documento\")\n\n  @@index([documento_id], map: \"idx_firma_documento\")\n  @@index([radicado], map: \"idx_firma_radicado\")\n  @@index([status], map: \"idx_firma_status\")\n}\n\nmodel identity_validations {\n  id              BigInt           @id @default(autoincrement())\n  radicado        String?          @unique(map: \"identity_validations_radicado_valida1_key\")\n  cedula          String?\n  request_json    Json?\n  response_json   Json?\n  created_at      DateTime         @default(now()) @db.Timestamptz(6)\n  updated_at      DateTime         @default(now()) @db.Timestamptz(6)\n  valida1_results valida1_results? @relation(fields: [radicado], references: [radicado], onUpdate: NoAction, map: \"fk_identity_valida1\")\n\n  @@index([cedula], map: \"idx_identity_cedula\")\n  @@index([radicado], map: \"idx_identity_radicado\")\n}\n\nmodel motor_data_results {\n  id              BigInt           @id @default(autoincrement())\n  radicado        String?\n  cedula          String?\n  request_json    Json?\n  response_json   Json?\n  created_at      DateTime         @default(now()) @db.Timestamptz(6)\n  updated_at      DateTime         @default(now()) @db.Timestamptz(6)\n  valida1_results valida1_results? @relation(fields: [radicado], references: [radicado], onUpdate: NoAction, map: \"fk_motor_data_valida1\")\n\n  @@index([cedula], map: \"idx_motor_data_cedula\")\n  @@index([radicado], map: \"idx_motor_data_radicado\")\n}\n\nmodel motor_process_results {\n  id              BigInt          @id @default(autoincrement())\n  radicado        String          @unique\n  cedula          String?\n  request_json    Json?\n  response_json   Json?\n  created_at      DateTime        @default(now()) @db.Timestamptz(6)\n  updated_at      DateTime        @default(now()) @db.Timestamptz(6)\n  valida1_results valida1_results @relation(fields: [radicado], references: [radicado], onDelete: Cascade, onUpdate: NoAction, map: \"fk_motor_process_valida1\")\n\n  @@index([cedula], map: \"idx_motor_process_cedula\")\n}\n\n/// Historial de ejecuciones del motor. `motor_process_results` guarda solo la\n/// vigente (una fila por radicado); aqui queda cada version anterior, incluida\n/// la que produjo el motor automatico.\n///\n/// Antes de sobrescribir la vigente se archiva aqui lo que habia, asi que la\n/// fila mas antigua es siempre el original. El diff de campos no se guarda: se\n/// calcula comparando dos filas consecutivas, para no duplicar el dato.\nmodel motor_ejecuciones {\n  id            BigInt @id @default(autoincrement())\n  radicado      String\n  request_json  Json?\n  response_json Json?\n\n  /// Correo del colaborador que la ejecuto. NULL = la corrio el motor\n  /// automatico, no una persona.\n  ejecutado_por String?\n  created_at    DateTime @default(now()) @db.Timestamptz(6)\n\n  valida1_results valida1_results @relation(fields: [radicado], references: [radicado], onDelete: Cascade, onUpdate: NoAction, map: \"fk_motor_ejecuciones_valida1\")\n\n  @@index([radicado, created_at(sort: Desc)], map: \"idx_motor_ejecuciones_radicado\")\n}\n\nmodel credito_decisiones {\n  id              BigInt          @id @default(autoincrement())\n  radicado        String          @unique\n  request_json    Json?\n  response_json   Json?\n  created_at      DateTime        @default(now()) @db.Timestamptz(6)\n  updated_at      DateTime        @default(now()) @db.Timestamptz(6)\n  valida1_results valida1_results @relation(fields: [radicado], references: [radicado], onDelete: Cascade, onUpdate: NoAction, map: \"fk_credito_valida1\")\n}\n\nmodel document_results {\n  id              BigInt           @id @default(autoincrement())\n  radicado        String?\n  cedula          String?\n  request_json    Json?\n  response_json   Json?\n  created_at      DateTime         @default(now()) @db.Timestamptz(6)\n  updated_at      DateTime         @default(now()) @db.Timestamptz(6)\n  valida1_results valida1_results? @relation(fields: [radicado], references: [radicado], onUpdate: NoAction, map: \"fk_document_valida1\")\n\n  @@index([cedula], map: \"idx_document_cedula\")\n  @@index([radicado], map: \"idx_document_radicado\")\n}\n\nmodel datos_asociado {\n  id                    BigInt   @id @default(autoincrement())\n  cedula                String   @unique\n  primer_apellido       String?\n  nombre                String?\n  nombre_asociado       String?\n  ciudad                String?\n  cliente_empresa       String?\n  estado_civil          String?\n  estado_civil_norm     String?\n  tipo_vivienda         String?\n  nivel                 String?\n  usuario_credito       String?\n  fecha_ingreso         String?\n  fecha_ingreso_empresa String?\n  edad                  Decimal? @db.Decimal\n  personas_cargo        Decimal? @db.Decimal\n  antiguedad_coop       Decimal? @db.Decimal\n  antiguedad_laboral    Decimal? @db.Decimal\n  salario               Decimal? @db.Decimal\n  aportes               Decimal? @db.Decimal\n  deuda_coopvalili      Decimal? @db.Decimal\n  cuota_disponible      Decimal? @db.Decimal\n  created_at            DateTime @default(now()) @db.Timestamptz(6)\n  updated_at            DateTime @default(now()) @db.Timestamptz(6)\n\n  @@index([cedula], map: \"idx_datos_asociado_cedula\")\n}\n"
}

